192	public class OrderRestController {
193	
194	    public record OrderSummary(Long id, OrderStatus status, long total, Long customerId) {
195	    }
196	
197	    public record LineDetail(String code, String name, String description, int quantity,
198	                             long unitPrice) {
199	    }
200	
201	    public record OrderDetail(Long id, OrderStatus status, long total, Customer customer,
202	                              List<LineDetail> lines) {
203	    }
204	
205	    private final OrderRepository orders;
206	    private final OrderLineRepository lines;
207	    private final CustomerRepository customers;
208	    private final ItemRepository items;
209	
210	    public OrderRestController(OrderRepository orders, OrderLineRepository lines,
211	                               CustomerRepository customers, ItemRepository items) {
212	        this.orders = orders;
213	        this.lines = lines;
214	        this.customers = customers;
215	        this.items = items;
216	    }
217	
218	    @GetMapping("/orders")
219	    public List<OrderSummary> list() {
220	        return orders.findTop20ByOrderById().stream()
221	                .map(o -> new OrderSummary(o.getId(), o.getStatus(), o.getTotal(),
222	                        o.getCustomerId()))
223	                .toList();
224	    }
225	
226	    @GetMapping("/orders/{id}")
227	    public OrderDetail detail(@PathVariable Long id) {
228	        Order order = orders.findById(id).orElseThrow(() -> new OrderNotFoundException(id));
229	        List<LineDetail> detail = lines.findByOrderId(id).stream()
230	                .map(line -> {
231	                    Item item = items.findById(line.getCode()).orElseThrow();
232	                    return new LineDetail(line.getCode(), item.getName(),
233	                            item.getDescription(), line.getQuantity(), line.getUnitPrice());
234	                })
235	                .toList();
236	        return new OrderDetail(order.getId(), order.getStatus(), order.getTotal(),
237	                customers.findById(order.getCustomerId()).orElseThrow(), detail);
238	    }
239	
240	    @GetMapping("/customers/{id}")
241	    public Customer customer(@PathVariable Long id) {
242	        return customers.findById(id).orElseThrow();
243	    }
244	}
