425	import java.util.function.Function;
426	import java.util.stream.Collectors;
427	import org.springframework.data.domain.Limit;
428	import org.springframework.data.domain.ScrollPosition;
429	import org.springframework.data.domain.Sort;
430	import org.springframework.data.domain.Window;
431	import org.springframework.graphql.data.method.annotation.Argument;
432	import org.springframework.graphql.data.method.annotation.BatchMapping;
433	import org.springframework.graphql.data.method.annotation.MutationMapping;
434	import org.springframework.graphql.data.method.annotation.QueryMapping;
435	import org.springframework.graphql.data.method.annotation.SchemaMapping;
436	import org.springframework.graphql.data.method.annotation.SubscriptionMapping;
437	import org.springframework.graphql.data.query.ScrollSubrange;
438	import org.springframework.security.access.prepost.PreAuthorize;
439	import org.springframework.stereotype.Controller;
440	import reactor.core.publisher.Flux;
441	import reactor.core.publisher.Sinks;
442	
443	@Controller
444	public class StoreController {
445	
446	    private final OrderRepository orders;
447	    private final OrderLineRepository lines;
448	    private final CustomerRepository customers;
449	    private final ItemRepository items;
450	    private final OrderService service;
451	    private final Sinks.Many<Order> statusChanges =
452	            Sinks.many().multicast().onBackpressureBuffer();
453	
454	    public StoreController(OrderRepository orders, OrderLineRepository lines,
455	                          CustomerRepository customers, ItemRepository items,
456	                          OrderService service) {
457	        this.orders = orders;
458	        this.lines = lines;
459	        this.customers = customers;
460	        this.items = items;
461	        this.service = service;
462	    }
463	
464	    @QueryMapping
465	    public Order order(@Argument Long id) {
466	        return orders.findById(id).orElseThrow(() -> new OrderNotFoundException(id));
467	    }
468	
469	    // first/after and last/before arrive as a ScrollSubrange; the Window that
470	    // comes back becomes an OrderConnection with edges, cursors and pageInfo.
471	    @QueryMapping
472	    public Window<Order> orders(ScrollSubrange subrange) {
473	        ScrollPosition position = subrange.position().orElse(ScrollPosition.keyset());
474	        int count = subrange.count().orElse(10);
475	        return orders.findBy(position, Limit.of(count), Sort.by("id"));
476	    }
477	
478	    @MutationMapping
479	    public Order shipOrder(@Argument Long id) {
480	        Order order = service.ship(id);
481	        statusChanges.tryEmitNext(order);
482	        return order;
483	    }
484	
485	    @SubscriptionMapping
486	    public Flux<Order> orderStatus(@Argument Long orderId) {
487	        return statusChanges.asFlux().filter(order -> order.getId().equals(orderId));
488	    }
489	
490	    // One query for the customers of every order in the response.
491	    @BatchMapping
492	    public Map<Order, Customer> customer(List<Order> batch) {
493	        Map<Long, Customer> byId = customers
494	                .findAllById(batch.stream().map(Order::getCustomerId).toList())
495	                .stream()
496	                .collect(Collectors.toMap(Customer::getId, Function.identity()));
497	        return batch.stream().collect(Collectors.toMap(
498	                Function.identity(), order -> byId.get(order.getCustomerId())));
499	    }
500	
501	    @BatchMapping
502	    public Map<Order, List<OrderLine>> lines(List<Order> batch) {
503	        Map<Long, List<OrderLine>> byOrder = lines
504	                .findByOrderIdIn(batch.stream().map(Order::getId).toList())
505	                .stream()
506	                .collect(Collectors.groupingBy(OrderLine::getOrderId));
507	        return batch.stream().collect(Collectors.toMap(
508	                Function.identity(),
509	                order -> byOrder.getOrDefault(order.getId(), List.of())));
510	    }
511	
512	    @BatchMapping
513	    public Map<OrderLine, Item> item(List<OrderLine> batch) {
514	        Map<String, Item> byCode = items
515	                .findAllById(batch.stream().map(OrderLine::getCode).distinct().toList())
516	                .stream()
517	                .collect(Collectors.toMap(Item::getCode, Function.identity()));
518	        return batch.stream().collect(Collectors.toMap(
519	                Function.identity(), line -> byCode.get(line.getCode())));
520	    }
