522	    // Schema evolution: the new field is added beside the old one, and the old
523	    // one is deprecated rather than removed, so clients that ask for it keep working.
524	    @SchemaMapping
525	    public long amount(Order order) {
526	        return order.getTotal();
527	    }
528	
529	    // Field level security: without the role this one field is null, and the
530	    // rest of the response still arrives.
531	    @SchemaMapping
532	    @PreAuthorize("hasRole('ADMIN')")
533	    public String email(Customer customer) {
534	        return customer.getEmail();
