539	package dev.example.store;
540	
541	import graphql.GraphQLError;
542	import graphql.GraphqlErrorBuilder;
543	import graphql.schema.DataFetchingEnvironment;
544	import org.springframework.graphql.execution.DataFetcherExceptionResolverAdapter;
545	import org.springframework.graphql.execution.ErrorType;
546	import org.springframework.stereotype.Component;
547	
548	// Without this, an exception reaches the client as INTERNAL_ERROR with its
549	// message hidden. With it, a missing order is a NOT_FOUND the client can act on.
550	@Component
551	public class StoreExceptionResolver extends DataFetcherExceptionResolverAdapter {
552	
553	    @Override
554	    protected GraphQLError resolveToSingleError(Throwable ex, DataFetchingEnvironment env) {
555	        if (ex instanceof OrderNotFoundException) {
556	            return GraphqlErrorBuilder.newError(env)
557	                    .errorType(ErrorType.NOT_FOUND)
558	                    .message(ex.getMessage())
559	                    .build();
560	        }
561	        return null;
562	    }
563	}
