        Order order = new Order(customerId, 3_000, Instant.parse("2026-09-01T10:00:00Z"));
        ReflectionTestUtils.setField(order, "id", id);
        return order;
    }

    private static Window<Order> window(List<Order> content, boolean hasNext) {
        return Window.from(content,
                i -> ScrollPosition.forward(Map.of("id", content.get(i).getId())), hasNext);
    }

    @Test
    void orderCountIsCorrect() {
        given(orders.findById(2L)).willReturn(Optional.of(order(2L, 2L)));
        given(customers.findAllById(List.of(2L))).willReturn(List.of(grace));
        given(orders.countByCustomerIdIn(List.of(2L))).willReturn(List.of(new Count(2L, 10)));

        graphQlTester.document("{ order(id: 2) { customer { id orderCount } } }")
                .execute()
                .path("order.customer.orderCount").entity(Integer.class).isEqualTo(10);
    }

    @Test
    @SuppressWarnings("unchecked")
    void orderCountIsOneQueryForEveryCustomerInTheResponse() {
        List<Order> page = List.of(order(1L, 1L), order(2L, 2L), order(3L, 3L), order(4L, 1L));
        given(orders.findBy(any(), any(), any())).willReturn(window(page, false));
        given(customers.findAllById(anyCollection())).willReturn(List.of(ada, grace, linus));
        // Linus has no orders, so the grouped query has no row for him.
        given(orders.countByCustomerIdIn(anyCollection()))
                .willReturn(List.of(new Count(1L, 10), new Count(2L, 7)));

        graphQlTester.document("{ orders(first: 4) { edges { node { customer { id orderCount } } } } }")
                .execute()
                .path("orders.edges[*].node.customer.orderCount").entityList(Integer.class)
                .containsExactly(10, 7, 0, 10);

        ArgumentCaptor<Collection<Long>> ids = ArgumentCaptor.forClass(Collection.class);
        verify(orders, times(1)).countByCustomerIdIn(ids.capture());
        assertThat(ids.getValue()).containsExactlyInAnyOrder(1L, 2L, 3L);
    }

    @Test
    void firstPageOfOneCustomer() {
        given(customers.existsById(2L)).willReturn(true);
        given(orders.findByCustomerId(eq(2L), any(), eq(Limit.of(3)), eq(Sort.by("id"))))
                .willReturn(window(List.of(order(2L, 2L), order(5L, 2L), order(8L, 2L)), true));
        given(customers.findAllById(anyCollection())).willReturn(List.of(grace));

        graphQlTester.document("""
                        { customerOrders(customerId: 2, first: 3) {
                            edges { node { id customer { id } } }
                            pageInfo { hasNextPage } } }""")
                .execute()
                .path("customerOrders.edges[*].node.id").entityList(String.class)
                .containsExactly("2", "5", "8")
                .path("customerOrders.edges[*].node.customer.id").entityList(String.class)
                .containsExactly("2", "2", "2")
                .path("customerOrders.pageInfo.hasNextPage").entity(Boolean.class).isEqualTo(true);
    }

    @Test
    void defaultPageIsTen() {
        given(customers.existsById(2L)).willReturn(true);
        given(orders.findByCustomerId(any(), any(), any(), any()))
                .willReturn(window(List.of(), false));

        graphQlTester.document("{ customerOrders(customerId: 2) { edges { node { id } } } }")
                .execute()
                .path("customerOrders.edges").entityList(Object.class).hasSize(0);

        verify(orders).findByCustomerId(eq(2L), eq(ScrollPosition.keyset()), eq(Limit.of(10)),
                eq(Sort.by("id")));
    }

    @Test
    void nextPageContinuesFromTheCursor() {
        given(customers.existsById(2L)).willReturn(true);
        given(orders.findByCustomerId(eq(2L), eq(ScrollPosition.keyset()), any(), any()))
                .willReturn(window(List.of(order(2L, 2L), order(5L, 2L)), true));
        given(orders.findByCustomerId(eq(2L), eq(ScrollPosition.forward(Map.of("id", 5L))),
                any(), any()))
                .willReturn(window(List.of(order(8L, 2L)), false));

        String cursor = graphQlTester
                .document("{ customerOrders(customerId: 2, first: 2) { pageInfo { endCursor } } }")
                .execute()
                .path("customerOrders.pageInfo.endCursor").entity(String.class).get();

        graphQlTester.document("""
                        query($after: String) { customerOrders(customerId: 2, first: 2, after: $after) {
                            edges { node { id } } pageInfo { hasNextPage } } }""")
                .variable("after", cursor)
                .execute()
                .path("customerOrders.edges[*].node.id").entityList(String.class)
                .containsExactly("8")
                .path("customerOrders.pageInfo.hasNextPage").entity(Boolean.class).isEqualTo(false);

        ArgumentCaptor<ScrollPosition> positions = ArgumentCaptor.forClass(ScrollPosition.class);
        verify(orders, times(2)).findByCustomerId(eq(2L), positions.capture(), any(), any());
        assertThat(positions.getAllValues().get(1)).isInstanceOfSatisfying(
                KeysetScrollPosition.class,
                keyset -> assertThat(keyset.getKeys()).containsEntry("id", 5L));
    }

    @Test
    void unknownCustomerIsNotFound() {
        given(customers.existsById(42L)).willReturn(false);

        graphQlTester.document("{ customerOrders(customerId: 42) { edges { node { id } } } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND
                        && error.getMessage().contains("No customer 42"));

        verify(orders, never()).findByCustomerId(any(), any(), any(), any());
    }
}
